K, W, C = 'Knowledge', 'Wisdom', 'Command'
S, R = 'stated', 'reflection'
def ins(t, b, text): return {'type': t, 'basis': b, 'text': text}
def keeps(t): return {'dir': 'keeps', 'text': t}
def loses(t): return {'dir': 'loses', 'text': t}
def between(t): return {'dir': 'between', 'text': t}
AGREE = between("Hebrew, Greek, Latin and King James agree in substance; only the rendering of the divine name and small turns of phrase differ.")
FORMULA = [between("The Latin, Greek and King James all have the speech formula; the divine name is rendered 'the Lord' outside the Hebrew.")]
TIMES = [loses("Hebrew 'appointed times' (mo'adim) is lost."), keeps("Greek 'feasts'."), between("The Latin and King James also have 'feasts'.")]
FIRE = [loses("Hebrew 'offering by fire' is lost."), keeps("Greek 'whole burnt offerings', a narrower category."), between("The Latin and King James have 'offering made by fire' or 'sacrifice'.")]
WAVE = [loses("Hebrew 'wave' is lost."), keeps("Greek 'offer up' or 'present'."), between("The Latin and King James have 'lift up' or 'wave'.")]
BOOTH = [loses("Hebrew 'booths' (sukkot) is lost."), keeps("Greek 'tents'."), between("The Latin and King James have 'tabernacles' or 'booths'.")]
AFFLICT = [loses("Hebrew 'afflict yourselves' is lost."), keeps("Greek 'humble your souls'."), between("The Latin and King James have 'afflict your souls'.")]

def v(received, explain, shared, k, w, lost, entries=None, cmd=None):
    inst = [ins(K, S, k)]
    if cmd: inst.append(ins(C, S, cmd))
    inst.append(ins(W, R, w))
    return {'received': received, 'explain': explain, 'shared': shared, 'instructions': inst, 'entries': entries if entries is not None else [], 'lost': lost}

